    range.textContent = 'Du ' + dayLabel.format(new Date(date.value+'T12:00:00Z')) + ' au ' + dayLabel.format(new Date(addDays(date.value,DAYS_PER_PAGE-1)+'T12:00:00Z'))
  }
  let showingLoader = false, exitAnimation, revealAnimations = []
  let period = 'all', days = [], selected = null, busy = false, locked = false, generation = 0, abort
  function controls() {
    next.disabled = busy || locked
    previous.disabled = busy || locked || !date.value || !date.validity.valid || date.value <= date.min
    retry.disabled = busy || locked
    if (changeSlot) changeSlot.disabled = locked
    date.disabled = locked
    filters.forEach(button => { button.disabled = locked })
    slots.querySelectorAll('button').forEach(button => { button.disabled = locked })
  }
  function clearSelection() { selected = null; collapse(false); onSelect(null) }
  function render() {
    slots.replaceChildren()
    slots.hidden = busy
    if (busy) {
      if (!showingLoader) {
        status.textContent = 'recherche des disponibilités'
        loadingIndicator?.start()
        showingLoader = true
      }
      controls()
      return
    }
    let count = 0
    for (const day of days) {
      const available = suggestedSlots(day.slots).filter(slot => matchesPeriod(slot, period))
      if (!available.length) continue
      count += available.length
      const section = document.createElement('section')
      const title = document.createElement('h4')
      title.textContent = dayLabel.format(new Date(`${day.date}T12:00:00Z`))
      const group = document.createElement('div')
      group.className = 'booking-day-times'
