          if (choiceLabel) choiceLabel.textContent = `Votre créneau : ${dayLabel.format(new Date(slot.start))} à ${clock.format(new Date(slot.start)).replace(':', ' h ').replace(/ h 00$/, ' h')}`
          collapse(true)
          changeSlot?.focus?.({ preventScroll: true })
          slots.querySelectorAll('button').forEach(item => item.setAttribute('aria-pressed', String(item === button)))
          onSelect(slot, { keyboard: event.detail === 0 })
        })
        group.append(button)
      }
