      slots.append(section)
    }
    if (showingLoader) { loadingIndicator?.stop(); showingLoader = false }
    status.textContent = count ? 'Choisissez votre créneau ci-dessous.' : 'Aucun créneau pour ce filtre sur ces 3 jours. Changez de filtre ou consultez les jours suivants.'
