      exitAnimation = status.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 180, easing: 'cubic-bezier(0.23, 1, 0.32, 1)', fill: 'forwards' })
      await exitAnimation.finished.catch(() => {})
    }
    if (current !== generation) return
    exitAnimation?.cancel()
    exitAnimation = undefined
    busy = false
    render()
    if (message) { retry.hidden = false; status.textContent = message }
    if (!reduced) {
      revealAnimations = [status, slots].filter(element => element.animate).map(element =>
        element.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 200, easing: 'cubic-bezier(0.23, 1, 0.32, 1)' }))
    }
