    const requestController = abort
    const signal = requestController.signal
    clearSelection()
    days = []
    retry.hidden = true
    const start = date.value
    range.textContent = start && date.validity.valid ? `Du ${dayLabel.format(new Date(`${start}T12:00:00Z`))} au ${dayLabel.format(new Date(`${addDays(start, DAYS_PER_PAGE - 1)}T12:00:00Z`))}` : ''
