      if (!response.ok) throw Error('availability')
      const data = await response.json()
      if (!Array.isArray(data.days) || data.days.length !== DAYS_PER_PAGE || data.days.some((day,i) => !/^\d{4}-\d{2}-\d{2}$/.test(day.date) || (i && day.date !== addDays(data.days[i-1].date,1)) || !Array.isArray(day.slots) || day.slots.some(s => !s.id || !Number.isFinite(Date.parse(s.start))))) throw Error('invalid days')
      if (current !== generation) return
      const calendar = data.calendar || data.days
      if (!Array.isArray(calendar) || calendar.length > 33 || calendar.length < 3 || calendar.some((day,i)=>!/^\d{4}-\d{2}-\d{2}$/.test(day.date) || (i && day.date!==addDays(calendar[i-1].date,1)) || !Array.isArray(day.slots) || day.slots.some(s=>!s.id || !Number.isFinite(Date.parse(s.start))))) throw Error('invalid calendar')
      const until = Date.now()+CACHE_LIFETIME
      for (const day of calendar) calendarCache.set(day.date,{day,until})
      // Mémoire bornée ; conserver quelques périodes pour les allers-retours.
      for (const [key,entry] of calendarCache) if(entry.until<=Date.now()) calendarCache.delete(key)
      while(calendarCache.size>99) calendarCache.delete(calendarCache.keys().next().value)
      days = data.days
      date.value = days[0].date
      updateRange()
      seekingFirst = false
      await finishSearch(current, data.empty ? 'Aucun créneau trouvé sur la période recherchée de 31 jours. Consultez les jours suivants ou contactez-moi.' : undefined)
    } catch {
      if (current !== generation) return
      await finishSearch(current, days.length ? 'Recherche incomplète. Les créneaux affichés sont disponibles ; réessayez pour vérifier les autres jours.' : 'Les disponibilités ne se chargent pas. Réessayez ou appelez le 07 67 01 21 02.')
