    if (locked) return
    period = button.dataset.period
    filters.forEach(item => item.setAttribute('aria-pressed', String(item === button)))
    if (selected && !matchesPeriod(selected, period)) clearSelection()
    render()
  }))
  date.value = date.min
  date.addEventListener('change', () => { if (!locked) { seekingFirst = false; load() } })
  previous.addEventListener('click', () => {
    if (busy || locked || !date.value || !date.validity.valid || date.value <= date.min) return
    const target = addDays(date.value, -DAYS_PER_PAGE)
    seekingFirst = false
    date.value = target < date.min ? date.min : target
    load()
  })
  next.addEventListener('click', () => {
    if (busy || locked) return
    seekingFirst = false
    date.value = addDays(date.value || date.min, DAYS_PER_PAGE)
    load()
  })
  retry.addEventListener('click', () => load(true))
  changeSlot?.addEventListener('click', () => {
    if (locked) return
    collapse(false)
    const active = slots.querySelectorAll('button')
    const selectedButton = [...active].find(button => button.getAttribute('aria-pressed') === 'true')
    if (selectedButton) selectedButton.focus()
    else date.focus?.()
  })
  load()
  return { refresh: () => load(true), setLocked(value) { locked = value; controls() } }
}

